INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(44911, 'Job 36:15', 'Job', 36, 15, 'خو هغه مظلومان د ظلم نه بچ کوى، او د مصيبتونو په وخت کښې ورته خپل ځان څرګندوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_15.mp3', '', 1761754199, 1761754199),
(44912, 'Job 36:16', 'Job', 36, 16, 'ايُوبه، خُدائ پاک دې تا د خطرې نه وباسى، او هغه ځائ ته دې بوځى چرته چې غم نۀ وى. هغه ستا په دسترخوان باندې ښۀ ښۀ خوراکونه کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_16.mp3', '', 1761754199, 1761754199),
(44913, 'Job 36:17', 'Job', 36, 17, 'خو د نورو بدعملو په شان به پوره سزا تا ته ملاويږى، تۀ په عدالت او اِنصاف کښې راګېر يې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_17.mp3', '', 1761754199, 1761754199),
(44914, 'Job 36:18', 'Job', 36, 18, 'خبردار چې رشوت دې دوکه نۀ کړى، او دولت دې بې‌لارې نۀ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_18.mp3', '', 1761754199, 1761754199),
(44915, 'Job 36:19', 'Job', 36, 19, 'ستا دولت او ستا طاقت ټول به تا د تکليف نه بچ کړى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_19.mp3', '', 1761754199, 1761754199),
(44916, 'Job 36:20', 'Job', 36, 20, 'د شپې د راتلو خواهش مۀ کوه، د هغه وخت چې کله قومونه تباه کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_20.mp3', '', 1761754199, 1761754199),
(44917, 'Job 36:21', 'Job', 36, 21, 'خبردار، چې د بدعملۍ طرف ته وانۀ وړې، خُدائ پاک ځکه په تکليف کړے يې چې په بدعملۍ کښې آخته نۀ شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_21.mp3', '', 1761754199, 1761754199),
(44918, 'Job 36:22', 'Job', 36, 22, 'ياد ساته چې د خُدائ پاک طاقت څومره لوئ دے، او هغه د ټولو نه عظيم اُستاذ دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_22.mp3', '', 1761754199, 1761754199),
(44919, 'Job 36:23', 'Job', 36, 23, 'هيڅوک خُدائ پاک ته دا نۀ شى وئيلے چې هغه به څۀ کوى، او څوک ورته وئيلے شى چې تا غلط کار کړے دے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_23.mp3', '', 1761754199, 1761754199),
(44920, 'Job 36:24', 'Job', 36, 24, 'څۀ چې هغه کوى په هغې تل د هغۀ تعريف کيږى. تۀ هم د هغۀ ثناء صِفت کوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_24.mp3', '', 1761754199, 1761754199),
(44921, 'Job 36:25', 'Job', 36, 25, 'ټولو خلقو دې ته کتلى دى، هر يو کس د لرې نه دې ته ګورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_25.mp3', '', 1761754199, 1761754199),
(44922, 'Job 36:26', 'Job', 36, 26, 'بې‌شکه خُدائ پاک لوئ دے او مونږ د هغۀ د لويئ اندازه هم نۀ شُو لګولے، د هغۀ د کالونو شمېر نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_26.mp3', '', 1761754199, 1761754199),
(44923, 'Job 36:27', 'Job', 36, 27, 'ځکه چې هغه نمى اوچتوى، او په باران يې بدلوى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_27.mp3', '', 1761754199, 1761754199),
(44924, 'Job 36:28', 'Job', 36, 28, 'هغه وريځې جوړوى او په هر چا باران راوروى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_28.mp3', '', 1761754199, 1761754199),
(44925, 'Job 36:29', 'Job', 36, 29, 'څوک د وريځو په خورېدو باندې پوهيږى، او د آسمان په تندر باندې پوهيږى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_29.mp3', '', 1761754199, 1761754199),
(44926, 'Job 36:30', 'Job', 36, 30, 'ګوره، هغه په آسمان کښې برېښنا راولى خو د سمندر بېخ کښې تيارۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_30.mp3', '', 1761754199, 1761754199),
(44927, 'Job 36:31', 'Job', 36, 31, 'ځکه چې د دې په ذريعه هغه په خلقو حکومت کوى، او هغه خلقو له بې‌حسابه خوراک ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_31.mp3', '', 1761754199, 1761754199),
(44928, 'Job 36:32', 'Job', 36, 32, 'هغه برېښنا په خپلو لاسونو کښې ساتى، او حُکم ورکوى چې نښه وولى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_32.mp3', '', 1761754199, 1761754199),
(44929, 'Job 36:33', 'Job', 36, 33, 'د هغۀ د تندر آواز داسې وائى، چې هغه غېرتى دے او د ګناه خِلاف غصه لرى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job36_verse_33.mp3', '', 1761754199, 1761754199),
(44930, 'Psalms 99:1', 'Psalms', 99, 1, 'پاچاهي کوي څښتن نو ودې لړزیږي د دنیا قومونه هغه دی ناست په تخت د اسماني مخلوق دپاسه نو ځمکه دې شي په لړزېدلو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms99_verse_1.mp3', '', 1761754199, 1761754199),
(44931, 'Psalms 99:2', 'Psalms', 99, 2, 'څښتن لویي څرګندوي صهیون کې او دی اوچت په ټولو ولسونو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms99_verse_2.mp3', '', 1761754199, 1761754199),
(44932, 'Psalms 99:3', 'Psalms', 99, 3, 'هغوی دې ووایي ثنا د هغه د لوی او هیبتناکه نامه ځکه چې دی هغه سپېڅلی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms99_verse_3.mp3', '', 1761754199, 1761754199),
(44933, 'Psalms 99:4', 'Psalms', 99, 4, 'ای ځواکمن پاچا، مینه لرې د عدالت سره ته تا قایم کړلو انصاف په اسراییلو کې دې کړی عدالت او نېکي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms99_verse_4.mp3', '', 1761754199, 1761754199),
(44934, 'Psalms 99:5', 'Psalms', 99, 5, 'ثنا او صفت وکړئ زمونږ د څښتن خدای د تخت په مخکې یې د پښو په چوکۍ وکړئ سجده ځکه چې دی هغه سپېڅلی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms99_verse_5.mp3', '', 1761754199, 1761754199),
(44935, 'Psalms 99:6', 'Psalms', 99, 6, 'موسی او هارون وو د هغه کاهنان او سموییل هم د هغې ډلې ؤ چې نوم یې د څښتن یاداوه څښتن ته یې وکړلو فریاد او هغه قبول یې کړ سوال', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms99_verse_6.mp3', '', 1761754199, 1761754199),
(44936, 'Psalms 99:7', 'Psalms', 99, 7, 'د ورېځ له منځه یې له دوی سره خبرې وکړې هغوی ومنل احکام او قوانین د هغه چې یې ورکړي وو هغوی ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms99_verse_7.mp3', '', 1761754199, 1761754199),
(44937, 'Psalms 99:8', 'Psalms', 99, 8, 'ای څښتنه! ای زمونږه خدایه! تا کړ قبول د خپلو خلکو سوال ته د هغوی بخښونکی خدای وې سره له دې چې تا د دوی د ګناهونو سزا ورکړه دوی ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms99_verse_8.mp3', '', 1761754199, 1761754199),
(44938, 'Psalms 99:9', 'Psalms', 99, 9, 'زمونږ د څښتن خدای ثنا او صفت وکړئ عبادت وکړئ د هغه په سپېڅلي غره باندې ځکه سپېڅلی دی زمونږ څښتن خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms99_verse_9.mp3', '', 1761754199, 1761754199),
(44939, 'Psalms 8:1', 'Psalms', 8, 1, 'ای څښتنه، زمونږ باداره! په ټول جهان کې د ستا نوم لوی دی ستا ثنا او صفت رسیږي تر اسمانه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms8_verse_1.mp3', '', 1761754199, 1761754199),
(44940, 'Psalms 8:2', 'Psalms', 8, 2, 'ماشومان او تي رودونکي ماشومان ستا د لویۍ سندرې وایي تا جوړه کړې ده قوي کلا د خپلو دښمنانو په ضد هم په خپله چوپ کوې مخالفان خپل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms8_verse_2.mp3', '', 1761754199, 1761754199),
(44941, 'Psalms 8:3', 'Psalms', 8, 3, 'کله چې وګورم اسمان ته چې جوړ کړی دی تا ستوري سپوږمۍ ته چې ځای په ځای کړي دي تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms8_verse_3.mp3', '', 1761754199, 1761754199),
(44942, 'Psalms 8:4', 'Psalms', 8, 4, 'نو انسان څه دی چې ته یې خیال ساتې؟ فاني انسان چې ته پرې پام ساتې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms8_verse_4.mp3', '', 1761754199, 1761754199),
(44943, 'Psalms 8:5', 'Psalms', 8, 5, 'ځان پسې دوهمه درجه دې ده ورکړې ده ته تاج د عزت او شان شوکت دې ورته ایښی په سر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms8_verse_5.mp3', '', 1761754199, 1761754199),
(44944, 'Psalms 8:6', 'Psalms', 8, 6, 'تا مقرر کړل دوی په هرڅه چې جوړ کړي دي تا د دوی په واک کې دې ورکړي ټول شیان دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms8_verse_6.mp3', '', 1761754199, 1761754199),
(44945, 'Psalms 8:7', 'Psalms', 8, 7, 'هم دې ورکړي ټول پسونه او غویان او وحشي حیوانات', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms8_verse_7.mp3', '', 1761754199, 1761754199),
(44946, 'Psalms 8:8', 'Psalms', 8, 8, 'هم د هوا مرغان او د دریاب ماهیان دا ټول مخلوقات چې په دریاب کې ګرځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms8_verse_8.mp3', '', 1761754199, 1761754199),
(44947, 'Psalms 8:9', 'Psalms', 8, 9, 'ای څښتنه، زمونږ باداره! په ټول جهان کې د ستا نوم لوی دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms8_verse_9.mp3', '', 1761754199, 1761754199),
(44948, 'Isaiah 64:1', 'Isaiah', 64, 1, 'کاشکې اسمان سوری کړې او لاندې راښکته شې او غرونه ستا په لیدلو په لړزېدلو شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah64_verse_1.mp3', '', 1761754199, 1761754199),
(44949, 'Isaiah 64:2', 'Isaiah', 64, 2, 'لکه څنګه چې د لرګیو په سوځېدلو اوبه خوټیږي، نو ستا په راتګ سره به قومونه په لړزېدلو شي. بیا به ستا نوم د دښمنانو په منځ کې مشهور شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah64_verse_2.mp3', '', 1761754199, 1761754199),
(44950, 'Isaiah 64:3', 'Isaiah', 64, 3, 'پخوا کله چې تا هیبتناکه کارونه وکړل چې مونږ یې هېڅ توقع نه لرله، ستا په راښکته کېدو غرونو ټکان وخوړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah64_verse_3.mp3', '', 1761754199, 1761754199),
(44951, 'Isaiah 64:4', 'Isaiah', 64, 4, 'هېڅکله هېچا ستا په شان خدای نه دی لیدلی او نه چا اورېدلی دی. یوازې ته هغه خدای یې چې د هغو خلکو سره مرسته کوې چې د هیلې سترګې یې تاته دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah64_verse_4.mp3', '', 1761754199, 1761754199),
(44952, 'Isaiah 64:5', 'Isaiah', 64, 5, 'ته هغو خلکو ته هرکلی وایې چې په خوشحالۍ سره عادلانه کارونه سرته رسوي او هغوی به په یاد ساتي چې ستا د رضا سره سم ژوند وکړي. ګوره، ته په مونږ په قهر شوې، خو مونږ ګناه پرېنښودله. که چېرې تل ستا د رضا سره سم ژوند وکړو، نو وبه ژغورل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah64_verse_5.mp3', '', 1761754199, 1761754199),
(44953, 'Isaiah 64:6', 'Isaiah', 64, 6, 'مونږ ټول ګناهکاران یو، حتی زمونږ ډېر ښه عملونه هم لکه د یوې نجسې ټوټې په شان دي. مونږ ټول لکه د مني د پاڼو غوندې مړاوې کېږو او ګناه مو لکه د باد پناه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah64_verse_6.mp3', '', 1761754199, 1761754199),
(44954, 'Isaiah 64:7', 'Isaiah', 64, 7, 'هېڅوک په دعا کې ستا نوم نه اخلي، هېڅوک په وفادارۍ سره ستا عبادت نه کوي. ځکه تا خپل مخ زمونږ نه اړولی دی او مونږ دې د ګناه په منګولو کې پریښي یو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah64_verse_7.mp3', '', 1761754199, 1761754199),
(44955, 'Isaiah 64:8', 'Isaiah', 64, 8, 'خو ای څښتنه، ته زمونږ پلار یې. مونږ لکه د خټې په شان یو او ته زمونږ دپاره لکه د کلال په شان یې. مونږ ټول ستا په لاس جوړ شوي یو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah64_verse_8.mp3', '', 1761754199, 1761754199),
(44956, 'Isaiah 64:9', 'Isaiah', 64, 9, 'نو په مونږ باندې دومره مه په قهرېږه او زمونږ ګناهونه د تل دپاره مه در په یادوه. په مونږ پام وکړه، ځکه مونږ ټول ستا قوم یو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah64_verse_9.mp3', '', 1761754199, 1761754199),
(44957, 'Isaiah 64:10', 'Isaiah', 64, 10, 'ستا سپېڅلي ښارونه او صهیون هم په دښته بدل شوي دي او اورشلیم وران او ویجاړ پروت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah64_verse_10.mp3', '', 1761754199, 1761754199),
(44958, 'Isaiah 64:11', 'Isaiah', 64, 11, 'زمونږ د عبادت سپېڅلی او پرتمین ځای چې زمونږ نیکونو به په کې ستا ستاینه کوله، په اور سوځول شوی او له منځه تللی دی. کوم ځایونه چې په مونږ باندې ګران وو هغه په کنډوالو باندې بدل شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah64_verse_11.mp3', '', 1761754199, 1761754199),
(44959, 'Isaiah 64:12', 'Isaiah', 64, 12, 'ای څښتنه، سره له دې چې مونږ دا ټول کړاوونه وزغمل، ایا بیاهم په مونږ رحم نه کوې؟ چوپ یې او مونږ ته له حده ډېره سزا راکوې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah64_verse_12.mp3', '', 1761754199, 1761754199),
(44960, 'Genesis 33:1', 'Genesis', 33, 1, 'یعقوب ولیدل چې عیسو د خپلو څلور سوه کسانو سره راروان دی. نو هغه خپل اولادونه په راحیل او لیه او دوه وینځو باندې ووېشل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_1.mp3', '', 1761754199, 1761754199),
(44961, 'Genesis 33:2', 'Genesis', 33, 2, 'وینځې او د هغوی اولادونه یې مخکې کړل. لیه او د هغې اولادونه یې ورپسې کړل او راحیل او یوسف یې شاته کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_2.mp3', '', 1761754199, 1761754199),
(44962, 'Genesis 33:3', 'Genesis', 33, 3, 'په خپله یعقوب د هغوی څخه مخکې روان ؤ. څنګه چې خپل ورور ته ورنژدې شو، اووه ځلې هغه ته د درناوي په خاطر په ځمکه باندې پړمخې پرېوت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_3.mp3', '', 1761754199, 1761754199),
(44963, 'Genesis 33:4', 'Genesis', 33, 4, 'خو عیسو په منډه د یعقوب هرکلي ته ورغی او هغه یې په غېږ کې ونیوه. خپل لاسونه یې د هغه د غاړې څخه راتاو کړل او ښکل یې کړ او دواړو وژړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_4.mp3', '', 1761754199, 1761754199),
(44964, 'Genesis 33:5', 'Genesis', 33, 5, 'بیا عیسو شاوخوا وکتل او ښځې او ماشومان یې ولیدل. هغه پوښتنه وکړه: «دا درسره څوک دي؟» یعقوب ځواب ورکړ: «دا زما اولادونه دي چې خدای په خپل فضل ماته راکړي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_5.mp3', '', 1761754199, 1761754199),
(44965, 'Genesis 33:6', 'Genesis', 33, 6, 'بیا وینځې د خپلو اولادونو سره راغلې او د درناوي په خاطر یې خپل سرونه ټیټ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_6.mp3', '', 1761754199, 1761754199),
(44966, 'Genesis 33:7', 'Genesis', 33, 7, 'بیا لیه او د هغې اولادونه راغلل او د ټولو څخه وروسته یوسف او راحیل راغلل او ټولو خپل سرونه د درناوي په خاطر ټیټ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_7.mp3', '', 1761754199, 1761754199),
(44967, 'Genesis 33:8', 'Genesis', 33, 8, 'عیسو پوښتنه وکړه: «دا ټول حیوانات چې ماته دې رالېږلي دي، د هغو څخه ستا مقصد څه دی؟» یعقوب ځواب ورکړ: «ای باداره، دا د دې دپاره دي چې تاسو راباندې مهرباني وکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_8.mp3', '', 1761754199, 1761754199),
(44968, 'Genesis 33:9', 'Genesis', 33, 9, 'خو عیسو وویل: «ای زما وروره، زما سره هرڅه ډېر دي. ستا سره چې هرڅه دي، خپل ځان ته یې وساته.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_9.mp3', '', 1761754199, 1761754199),
(44969, 'Genesis 33:10', 'Genesis', 33, 10, 'یعقوب ځواب ورکړ: «نه! که په ما باندې مهربانه شوی یې، نو زما سوغات قبول کړه. ځکه چې ستا د مخ لیدل زما دپاره لکه د خدای د مخ د لیدلو په شان دي، په دې خاطر چې زه دې په مهربانۍ سره قبول کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_10.mp3', '', 1761754199, 1761754199),
(44970, 'Genesis 33:11', 'Genesis', 33, 11, 'نو د مهربانۍ له مخې دا سوغاتونه چې ستا دپاره مې راوړي دي قبول کړه، ځکه چې خدای په ما باندې فضل کړی دی او هرڅه ته چې زه اړتیا لرم، هغه ټول یې ماته راکړي دي.» یعقوب دومره ټینګار وکړ، تر هغې چې عیسو هغه قبول کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_11.mp3', '', 1761754199, 1761754199),
(44971, 'Genesis 33:12', 'Genesis', 33, 12, 'عیسو وویل: «راځئ چې لاړ شو. زه به تاسو بدرګه کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_12.mp3', '', 1761754199, 1761754199),
(44972, 'Genesis 33:13', 'Genesis', 33, 13, 'خو یعقوب هغه ته وویل: «زما بادار پوهیږي چې اولادونه مې کمزوري دي او زه باید په دې مېږو او غواګانو باندې چې لنګې دي، پام وکړم. که چېرې هغه په یوه ورځ کې سختې وځغلولې شي، نو ټول به مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_13.mp3', '', 1761754199, 1761754199),
(44973, 'Genesis 33:14', 'Genesis', 33, 14, 'نو زما بادار دې زما څخه مخکې لاړ شي او زه به ورو، ورو د اولادونو او حیواناتو په قدم درځم، ترڅو د خپل بادار سره په ادوم کې یوځای شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_14.mp3', '', 1761754199, 1761754199),
(44974, 'Genesis 33:15', 'Genesis', 33, 15, 'عیسو وویل: «نو بیا اجازه راکړه چې د خپلو کسانو څخه یو څو تنه ستا سره پرېږدم.» یعقوب ځواب ورکړ: «د دې اړتیا نشته، ځکه زه یوازې دا غواړم چې خپل بادار راباندې مهرباني وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_15.mp3', '', 1761754199, 1761754199),
(44975, 'Genesis 33:16', 'Genesis', 33, 16, 'په هماغه ورځ عیسو په خپله لاره روان شو او بېرته ادوم ته ستون شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_16.mp3', '', 1761754199, 1761754199),
(44976, 'Genesis 33:17', 'Genesis', 33, 17, 'خو یعقوب سوکوت ته لاړ او هلته یې د خپل ځان دپاره کور جوړ کړ او د خپلو حیواناتو دپاره یې څپرې جوړې کړې. نو ځکه هغه ځای د سوکوت په نوم یاد کړای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_17.mp3', '', 1761754199, 1761754199),
(44977, 'Genesis 33:18', 'Genesis', 33, 18, 'نو یعقوب د بین‌النهرین څخه په سلامتۍ سره د شکیم ښار ته چې په کنعان کې دی، راغی او ښار ته نژدې یې په یو ځای کې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_18.mp3', '', 1761754199, 1761754199),
(44978, 'Genesis 33:19', 'Genesis', 33, 19, 'هغه ځمکه چې په هغې کې یې خېمې ودرولې وې، هغه یې د شکیم د پلار حمور د اولادونو څخه د سپینو زرو په سلو سکو واخیستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_19.mp3', '', 1761754199, 1761754199),
(44979, 'Genesis 33:20', 'Genesis', 33, 20, 'هلته هغه د قربانۍ ځای جوړ کړ او هغه یې د ایل الوهي اسراییل په نوم یاد کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis33_verse_20.mp3', '', 1761754199, 1761754199),
(44980, 'Micah 5:1', 'Micah', 5, 1, 'ای د اورشلیم خلکو، خپل قوتونه سره راټول کړئ! ستاسو ښار کلابند شوی دی، دښمنان د اسراییلو مشر په کوتک باندې په مخ وهي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_1.mp3', '', 1761754199, 1761754199),
(44981, 'Micah 5:2', 'Micah', 5, 2, 'څښتن وایي: «خو ای د بیت‌لحم افراتې، که څه هم ته په یهودا کې ډېر کوچنی ښارګوټی یې، خو ستا نه به د اسراییلو دپاره یو حاکم رامنځته شي چې د هغه د کورنۍ نسب‌نامه د پخوا زمانو نه راروانه ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_2.mp3', '', 1761754199, 1761754199),
(44982, 'Micah 5:3', 'Micah', 5, 3, 'نو څښتن به خپل قوم تر هغه وخته پورې خپلو دښمنانو ته پرېږدي، ترڅو د هغې ښځې چي د لنګون په وخت کې ده، زوی وشي. بیا به هغه اسراییلیان چې جلاوطنه دي، بېرته د خپل قوم سره راستانه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_3.mp3', '', 1761754199, 1761754199),
(44983, 'Micah 5:4', 'Micah', 5, 4, 'کله چې هغه حاکم راشي، نو د څښتن په قدرت او په خپله د څښتن خدای د جلال سره به په خپل قوم باندې حکومت وکړي. د هغه قوم به په امن کې ژوند کوي، ځکه چې د هغه لویي به ټوله نړۍ وپېژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_4.mp3', '', 1761754199, 1761754199),
(44984, 'Micah 5:5', 'Micah', 5, 5, 'هغه به ارامي راولي. خلاصون او سزا کله چې آشوریان زمونږ په وطن باندې حمله وکړي او زمونږ دفاعي‌لیکه ماته کړي، نو مونږ به خپل ډېر قوي مشران ولېږو چې د هغوی سره وجنګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_5.mp3', '', 1761754199, 1761754199),
(44985, 'Micah 5:6', 'Micah', 5, 6, 'هغوی به د خپلو تورو په زور په آشور یعنې د نمرود په وطن باندې بریالي شي. کله چې آشوریان زمونږ د وطن د سرحد نه تېر شي چې حمله وکړي، نو هغه حاکم به مونږ د هغوی نه وژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_6.mp3', '', 1761754199, 1761754199),
(44986, 'Micah 5:7', 'Micah', 5, 7, 'د اسراییلو کوم جلا‌وطنه خلک چې ژوندي پاتې شوي دي، هغوی به د هغې تازه پرخې په شان وي چې څښتن په ټولو قومونو باندې اورولې وي او د هغه باران په شان به وي چې په شنو بوټو باندې اوریږي. هغوی به په خدای باندې توکل کوي، نه په انسانانو باندې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_7.mp3', '', 1761754199, 1761754199),
(44987, 'Micah 5:8', 'Micah', 5, 8, 'د نورو قومونو په منځ کې چې کوم اسراییلیان ژوندي پاتې دي، هغوی به د هغه زمري په شان وي چې په ځنګل کې د خوراک په لټه کې وي. هغه د پسونو منځ ته ورننوځي، په هغوی باندې به ناڅاپه ورټوپ کړي او هغه پسونه به ټوټې ټوټې کړي او هېڅ خلاصوونکی به نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_8.mp3', '', 1761754199, 1761754199),
(44988, 'Micah 5:9', 'Micah', 5, 9, 'په دې ډول اسراییل به په خپلو دښمنانو باندې بریالی شي او هغوی ټول به له منځه یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_9.mp3', '', 1761754199, 1761754199),
(44989, 'Micah 5:10', 'Micah', 5, 10, 'څښتن اسراییلو ته وایي: «په هغه وخت کې به زه ستاسو اسونه ووژنم او جنګي ګاډۍ به مو له منځه یوسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_10.mp3', '', 1761754199, 1761754199),
(44990, 'Micah 5:11', 'Micah', 5, 11, 'زه به ستاسو د وطن ښارونه وران کړم او ستاسو ټولې قوي کلاګانې به راوغورځوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_11.mp3', '', 1761754199, 1761754199),
(44991, 'Micah 5:12', 'Micah', 5, 12, 'زه به ستاسو جادوګري له منځه یوسم او فال‌کتونکي به نور نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_12.mp3', '', 1761754199, 1761754199),
(44992, 'Micah 5:13', 'Micah', 5, 13, 'زه به ستاسو بتان او د تیږو ستنې له منځه یوسم او نور به تاسو هغو شیانو ته عبادت نه کوئ چې تاسو په خپلو لاسونو باندې جوړ کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_13.mp3', '', 1761754199, 1761754199),
(44993, 'Micah 5:14', 'Micah', 5, 14, 'زه به ستاسو په وطن کې د اشیره د بت مجسمې راوغورځوم او ستاسو ښارونه به وران کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_14.mp3', '', 1761754199, 1761754199),
(44994, 'Micah 5:15', 'Micah', 5, 15, 'زه به په خپل سخت قهر سره د هغو قومونو نه بدل واخلم چې زما اطاعت یې نه دی کړی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah5_verse_15.mp3', '', 1761754199, 1761754199),
(44995, 'Nehemiah 7:1', 'Nehemiah', 7, 1, 'نو دېوال ودان شو، ټولې دروازې په خپلو ځایونو کې کېښودل شوې او د خدای د کور ساتونکو، سندرغاړو او لاویانو ته خپل کارونه وسپارل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah7_verse_1.mp3', '', 1761754199, 1761754199),
(44996, 'Nehemiah 7:2', 'Nehemiah', 7, 2, 'دوه کسان مې د اورشلیم د ښار د اداره کولو دپاره د چارواکو په توګه وټاکل: زما ورور حناني او د جنګي کلا قوماندان حننیا. حننیا د ډېرو خلکو په پرتله یو اعتباري سړی ؤ او له خدایه وېرېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah7_verse_2.mp3', '', 1761754199, 1761754199),
(44997, 'Nehemiah 7:3', 'Nehemiah', 7, 3, 'ما هغوی ته وویل: «د اورشلیم دروازې تر هغه وخته پورې مه خلاصوئ، ترڅو لمر ښه نه وي راختلی او د لمر پرېوتلو په وخت کې یې د ساتونکو د رخصتېدلو څخه مخکې تړئ او اړم ورته اچوئ.» هغوی ته مې دا هم وویل چې د اورشلیم د اوسېدونکو څخه ساتونکي وټاکي او د هغوی څخه ځینې کسان پوستو ته ورکړي او نور دې د خپلو کورونو په شاوخوا سیمه کې ګزمه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah7_verse_3.mp3', '', 1761754199, 1761754199),
(44998, 'Nehemiah 7:4', 'Nehemiah', 7, 4, 'اورشلیم یو لوی او پراخه ښار ؤ، خو ډېر خلک په کې نه اوسېدل او تر هغه وخته پورې لا کورونه په کې بېرته جوړ شوي نه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah7_verse_4.mp3', '', 1761754199, 1761754199),
(44999, 'Nehemiah 7:5', 'Nehemiah', 7, 5, 'خدای دا فکر زما په زړه کې واچاوه چې قوم او د هغوی مشران او مامورین د هغو د کورنیو د سوانحو د ثبتولو دپاره راټول کړم. ما د هغو خلکو نسب نامې راپیدا کړې چې د اسیرتوب څخه لومړی راستانه شوي وو او دا هغه معلومات دی چې ما راپیدا کړ:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah7_verse_5.mp3', '', 1761754199, 1761754199),
(45000, 'Nehemiah 7:6', 'Nehemiah', 7, 6, 'ډېرو جلاوطنو خلکو د بابل ولایت پرېښود او اورشلیم او یهودا ته یعنې خپلو ښارګوټو ته راستانه شول. له هغه وخت څخه چې نبوکدنصر پاچا هغوی د اسیرانو په توګه بابل ته بېولي وو، د هغوی کورنۍ هلته په جلاوطنۍ کې اوسېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah7_verse_6.mp3', '', 1761754199, 1761754199),
(45001, 'Nehemiah 7:7', 'Nehemiah', 7, 7, 'دا د هغوی مشران وو: زروبابل، یشوع، نحمیا، عزریا، رعمیا، نحماني، مردخای، بلشان، مسفارت، بغوای، نحوم او بعنه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah7_verse_7.mp3', '', 1761754199, 1761754199),
(45002, 'Nehemiah 7:60', 'Nehemiah', 7, 60, 'د خدای د کور د خدمتګارانو او د سلیمان د خدمتګارانو د اولادې ټول شمېر چې د جلاوطنۍ څخه راستانه شوي وو، ۳۹۲ تنه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah7_verse_60.mp3', '', 1761754199, 1761754199),
(45003, 'Nehemiah 7:65', 'Nehemiah', 7, 65, 'د یهودیانو والي هغوی ته وویل: «تر هغې پورې چې د کوم کاهن له خوا د اوریم او تمیم په وسیله معلومه نه شي چې تاسو په رښتیا سره کاهنان یئ، تاسو نه شئ کولای هغه ډوډۍ وخورئ چې خدای ته وړاندې کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah7_verse_65.mp3', '', 1761754199, 1761754199),
(45004, 'Nehemiah 7:73', 'Nehemiah', 7, 73, 'نو کاهنان، لاویان، د خدای د کور ساتونکي، سندرغاړي، نور خلک، د خدای د کور خدمتګاران یعنې د اسراییلو ټول قوم د یهودا په ښارګوټو او ښارونو کې ځای په ځای شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah7_verse_73.mp3', '', 1761754199, 1761754199),
(45005, 'Judges 11:1', 'Judges', 11, 1, 'یفتاح یو زړور عسکر ؤ چې د جلعاد څخه ؤ. د هغه د پلار نوم جلعاد ؤ او مور یې بدلمنه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_1.mp3', '', 1761754199, 1761754199),
(45006, 'Judges 11:2', 'Judges', 11, 2, 'جلعاد د خپلې نکاح کړې ښځې څخه نور زامن هم درلودل. کله چې هغوی لوی شول، نو یفتاح یې د کور څخه وویست او ورته ویې ویل: «ته به زمونږ په کورنۍ کې میراث تر لاسه نه کړې، ځکه چې ته د بلې ښځې زوی یې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_2.mp3', '', 1761754199, 1761754199),
(45007, 'Judges 11:3', 'Judges', 11, 3, 'نو یفتاح د خپلو ورونو څخه وتښتېد او د طوب په خاوره کې اوسېده او هلته د هغه په شاوخوا خوشې او بېکاره خلک راټول شول او په هغه پسې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_3.mp3', '', 1761754199, 1761754199),
(45008, 'Judges 11:4', 'Judges', 11, 4, 'څه موده وروسته عمونیانو د اسراییلو سره جنګ پیل کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_4.mp3', '', 1761754199, 1761754199),
(45009, 'Judges 11:5', 'Judges', 11, 5, 'نو د جلعاد مشران لاړل چې یفتاح د طوب د خاورې څخه راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_5.mp3', '', 1761754199, 1761754199),
(45010, 'Judges 11:6', 'Judges', 11, 6, 'هغوی هغه ته وویل: «راشه او زمونږ قوماندان شه، ترڅو مونږ وکولای شو د عمونیانو سره جګړه وکړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges11_verse_6.mp3', '', 1761754199, 1761754199);